@Test
    public void testLineOfCodeCount() {
        SourceFile file = SwiftAstScanner.scanSingleFile(new File("src/test/resources/Test.swift"));
        assertThat(file.getInt(SwiftMetric.LINES_OF_CODE), is(11));
    }

